import "core-js/modules/es.array.push.js";
import GoogleMaps from "@/components/GoogleMaps.vue";
export default {
  components: {
    GoogleMaps
  },
  props: {
    locationasset: Boolean,
    adminassetItems: Object
  },
  data() {
    return {
      mapCenter: {
        lat: 45.508,
        lng: -73.587
      },
      mapMarkers: [],
      places: [],
      currentPlace: null
    };
  },
  watch: {
    locationasset: {
      async handler() {
        if (this.locationasset == true) {
          if (this.adminassetItems.asset_location_lat != null && this.adminassetItems.asset_location_long != null) {
            this.mapMarkers = [];
            var marker = {
              position: {
                lat: Number(this.adminassetItems.asset_location_lat),
                lng: Number(this.adminassetItems.asset_location_long)
              }
            };
            this.mapMarkers.push(marker);
            this.mapCenter = marker.position;
          }
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    onMapsLoaded() {
      // console.log("Google Maps loaded successfully");
    },
    onMarkerClick() {
      // Handle marker click if needed
    }
  }
};
